CALLS = {"compute": 0}


def compute(key):
    CALLS["compute"] += 1
    return key * 2


CACHE: dict[int, int] = {}


def lookup(key):
    """The computed value for this key."""
    if key not in CACHE:
        CACHE[key] = compute(key)
    return CACHE[key]

REGISTRY: list = []


class Session:
    def __init__(self, name):
        self.name = name
        REGISTRY.append(self)

ALIVE: list[str] = []


class Node:
    def __init__(self, name, parent=None):
        self.name = name
        self.parent = parent
        self.children = []
        ALIVE.append(name)
        if parent is not None:
            parent.children.append(self)

    def __del__(self):
        ALIVE.remove(self.name)

def first_error(lines):
    """The first line reporting an error, or None."""
    everything = list(lines)
    for line in everything:
        if line.startswith("ERROR"):
            return line
    return None

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

def snapshot(rows):
    """A copy the caller's data cannot be changed through."""
    return rows[:]

def same_total(left, right):
    """Whether these two totals are the same amount."""
    return left is right
